      i.decorate('test', () => {})
      t.assert.ok(i.test)
      t.assert.ok(!i.otherTest)
      n()
    }))

    instance.get('/', (req, reply) => {
      t.assert.ok(instance.test)
      t.assert.ok(!instance.otherTest)
      reply.send({ hello: 'world' })
    })

    done()
  })

  fastify.ready(() => {
    t.assert.ok(!fastify.test)
  })

