    t.assert.deepEqual(req.getDecorator('utility')(), req)

    res.send()
  })

  fastify.ready((err) => {
    t.assert.ifError(err)
    fastify.inject({ url: '/' }, (err, res) => {
      t.assert.ifError(err)
      t.assert.ok(true, 'passed')
      done()
    })
  })
})

