        res.on('close', () => resolve())
        res.on('end', () => resolve())
      })
      req.on('error', () => resolve())
      req.end()
      const hangTimer = setTimeout(() => reject(new Error('response hung')), 2000)
      t.after(() => clearTimeout(hangTimer))
    })
  })
})

