  function routeHandler (req, res, params, context, query) {
    const id = getGenReqId(context.server, req)

    let childLogger
    if (hasLogger === false && context.childLoggerFactory === defaultChildLoggerFactory) {
      // the null logger children are the logger itself, so we can skip
      // the child logger creation altogether
      childLogger = logger
    } else {
      const loggerOpts = {}

      // An empty level means "inherit". Passing it would make pino treat it
      // as a level change and rebuild every log method of each request child.
      if (context.logLevel) {
        loggerOpts.level = context.logLevel
      }

      if (context.logSerializers) {
        loggerOpts.serializers = context.logSerializers
      }
      childLogger = createChildLogger(context, logger, req, id, loggerOpts)
    }

    if (closing === true) {
      /* istanbul ignore next mac, windows */
      if (req.httpVersionMajor !== 2) {
        res.setHeader('Connection', 'close')
      }

      // Load-shedding fast path during drain. server.close() and
      // closeIdleConnections() only reap idle sockets; requests already
      // pipelined or arriving on an active keep-alive connection still reach
      // this point with closing === true. Short-circuiting with 503 avoids
      // running the full handler chain (and any downstream calls) for work
      // the load balancer should redirect elsewhere.
      if (return503OnClosing) {
        const headers = {
          'Content-Type': 'application/json',
          'Content-Length': '80'
        }
        res.writeHead(503, headers)
        res.end('{"error":"Service Unavailable","message":"Service Unavailable","statusCode":503}')

        context.server[kLogController].serviceUnavailable(childLogger, context.server)

        return
      }
    }

    // When server.forceCloseConnections is true, we will collect any requests
    // that have indicated they want persistence so that they can be reaped
    // on server close. Otherwise, the container is a noop container.
    const connHeader = String.prototype.toLowerCase.call(req.headers.connection || '')
    if (connHeader === 'keep-alive') {
      if (keepAliveConnections.has(req.socket) === false) {
        keepAliveConnections.add(req.socket)
        req.socket.on('close', removeTrackedSocket.bind({ keepAliveConnections, socket: req.socket }))
      }
    }

    // we revert the changes in defaultRoute
    if (req.headers[kRequestAcceptVersion] !== undefined) {
      req.headers['accept-version'] = req.headers[kRequestAcceptVersion]
      req.headers[kRequestAcceptVersion] = undefined
    }

    const request = new context.Request(id, params, req, query, childLogger, context)
    const reply = new context.Reply(res, request, childLogger)

    context.server[kLogController].incomingRequest(request, reply)

    // Handler timeout setup — only when configured (zero overhead otherwise)
    const handlerTimeout = context.handlerTimeout
    if (handlerTimeout > 0) {
      const ac = new AbortController()
      request[kRequestSignal] = ac

      request[kTimeoutTimer] = setTimeout(() => {
        if (!reply.sent) {
          const err = new FST_ERR_HANDLER_TIMEOUT(handlerTimeout, context.config?.url)
          ac.abort(err)
          reply[kReplyIsError] = true
          reply.send(err)
        }
      }, handlerTimeout)

      const onAbort = () => {
        if (!ac.signal.aborted) {
          ac.abort()
        }
        clearTimeout(request[kTimeoutTimer])
      }
      req.on('close', onAbort)
      request[kOnAbort] = onAbort
    }

    if (hasLogger === true || context.onResponse !== null || handlerTimeout > 0) {
      setupResponseListeners(reply)
    }

    if (context.onTimeout !== null) {
      if (!request.raw.socket._meta) {
        request.raw.socket.on('timeout', handleTimeout)
      }
      request.raw.socket._meta = { context, request, reply, onTimeout: handleTimeout }
    }

    if (context.onRequest !== null) {
      onRequestHookRunner(
        context.onRequest,
        request,
        reply,
        runPreParsing
      )
    } else {
      runPreParsing(null, request, reply)
    }

    if (context.onRequestAbort !== null) {
      req.on('close', () => {
        /* istanbul ignore else */
        if (req.aborted) {
          onRequestAbortHookRunner(
            context.onRequestAbort,
            request,
            handleOnRequestAbortHooksErrors.bind(null, reply)
          )
        }
      })
    }
  }
}

